// Helper: generate a fresh exId for user-created entries.
function wsNewExId(){
  return 'ex_'+Math.random().toString(36).slice(2,9)+Date.now().toString(36).slice(-4);
}

// Unique id for a single exercise *instance* (one copy living in one day).
// Distinct from exId, which links the instance back to its library catalog
// entry. Many instances can share an exId (e.g. two copies of the same bench
// variation); each has its own iid. This is the true identity key used for
// dedup, reorder, removal, and (later) history tracking — never content.
function wsNewIid(){
  return 'i_'+Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-5);
}

// Ensure an instance has an iid; assign one if missing. Returns the iid.
function wsEnsureIid(inst){
  if(!inst) return null;
  if(!inst._iid) inst._iid=wsNewIid();
  return inst._iid;
}

// Helper: find a catalog entry by (title, subtitle, kind) match. Case-insensitive
// on title/subtitle; subtitle treated as empty if missing.
function wsFindCatalogEntry(title,subtitle,kind){
  const t=(title||'').trim().toLowerCase();
  const s=(subtitle||'').trim().toLowerCase();
  for(const e of EXERCISES){
    if(e.kind!==kind) continue;
    if((e.title||'').trim().toLowerCase()!==t) continue;
    if((e.subtitle||'').trim().toLowerCase()!==s) continue;
    return e;
  }
  return null;
}

// Helper: split a legacy "Title — Subtitle" name into its parts. Em-dash and
// hyphen-em-dash both common in existing data.
function wsSplitNameForCatalog(legacyName){
  if(!legacyName) return {title:'',subtitle:''};
  // Try " — " (em dash with spaces), " - " (hyphen with spaces).
  const sep=legacyName.indexOf(' — ');
  if(sep>=0) return {title:legacyName.slice(0,sep).trim(),subtitle:legacyName.slice(sep+3).trim()};
  const sep2=legacyName.indexOf(' - ');
  if(sep2>=0) return {title:legacyName.slice(0,sep2).trim(),subtitle:legacyName.slice(sep2+3).trim()};
  return {title:legacyName.trim(),subtitle:''};
}

// Migration: walk every exercise instance across all days. If its (title,
// subtitle, kind) matches a catalog entry, stamp that exId onto the instance.
// If no match, create a new catalog entry from the instance's data so the
// catalog covers everything the user already has.
function wsMigrateDayInstances(days){
  for(const day of days){
    if(day.exercises){
      for(const ex of day.exercises){
        if(ex.exId) continue;
        const {title,subtitle}=wsSplitNameForCatalog(ex.name);
        const found=wsFindCatalogEntry(title,subtitle,'weighted');
        if(found){
          ex.exId=found.exId;
        } else {
          // Create a new catalog entry from this instance's defaults.
          const newEntry={
            exId:wsNewExId(),title,subtitle,kind:'weighted',
            defaults:{
              cue:ex.cue||'',
              rest:ex.rest||90,
              sets:(ex.sets||[]).map(s=>({w:s.w,r:s.r})),
            },
            muscles:[],pattern:'',
          };
          EXERCISES.push(newEntry);
          ex.exId=newEntry.exId;
        }
      }
    }
    if(day.cardio){
      for(const ex of day.cardio){
        if(ex.exId) continue;
        const cardioKind = ex.kind==='time'?'cardio_time'
                         : ex.kind==='distance'?'cardio_distance'
                         : ex.kind==='intervals'?'cardio_intervals'
                         : 'cardio_time';
        const {title,subtitle}=wsSplitNameForCatalog(ex.name);
        const found=wsFindCatalogEntry(title,subtitle,cardioKind);
        if(found){
          ex.exId=found.exId;
        } else {
          // Build defaults capturing this cardio instance.
          const d={cue:ex.cue||'',icon:ex.icon||''};
          if(cardioKind==='cardio_time'){
            d.duration=ex.duration||300;
            d.intensity=ex.intensity||'Mod';
          } else if(cardioKind==='cardio_distance'){
            d.distance=ex.distance||5;
            d.duration=ex.duration||1800;
          } else if(cardioKind==='cardio_intervals'){
            d.workSec=ex.workSec||30;
            d.restSec=ex.restSec||15;
            d.totalRounds=ex.totalRounds||4;
            d.simpleMode=ex.simpleMode!==false;
            d.roundsCustom=(ex.roundsCustom||[]).map(r=>({name:r.name,work:r.work,rest:r.rest}));
          }
          const newEntry={
            exId:wsNewExId(),title,subtitle,kind:cardioKind,
            defaults:d,muscles:[],pattern:'',
          };
          EXERCISES.push(newEntry);
          ex.exId=newEntry.exId;
        }
      }
    }
  }
}
